import React, { useEffect, useRef } from 'react';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';

function TerminalComponent({ containerId }) {
  const terminalRef = useRef(null);
  const socketRef = useRef(null);
  const terminal = useRef(null);
  const fitAddon = useRef(new FitAddon()).current; // Ensure FitAddon is only created once

  useEffect(() => {
    // Check if terminalRef is available
    if (!terminalRef.current) return;

    // Initialize xterm.js terminal
    const terminal = new Terminal();
    terminal.loadAddon(fitAddon);

    // Open the terminal in the specified ref
    terminal.open(terminalRef.current);
    fitAddon.fit();

    // Establish WebSocket connection to the backend
    const socket = new WebSocket('ws://localhost:3001');
    socketRef.current = socket;

    socket.onopen = () => {
      socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' })); // Start a shell in the container
    };

    // Handle messages from the backend and display them in the terminal
    socket.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        terminal.write(message.output);
      } else if (message.error) {
        terminal.write(`\x1B[31m${message.error}\x1B[0m`); // Display errors in red
      } else if (message.message) {
        terminal.write(message.message);
      }
    };

    // Send terminal input to the WebSocket
    terminal.onData((input) => {
      socket.send(JSON.stringify({ containerId, cmd: input }));
    });

    // Handle terminal resize on window resize
    const handleResize = () => {
      fitAddon.fit();
    };

    window.addEventListener('resize', handleResize);

    // Cleanup on component unmount
    return () => {
      socket.close();
      terminal.dispose();
      window.removeEventListener('resize', handleResize);
    };
  }, [containerId]); // Dependency on containerId to reconnect if it changes

  return <div ref={terminalRef} style={{ width: '100%', height: '100%' }} />;
}

export default TerminalComponent;
